using MongoDB.Bson;
using MongoDB.Driver;
using VirGo.Application.Marketplace;
using VirGo.Domain.Marketplace;

namespace VirGo.Infrastructure;

public sealed class InMemoryConversationRepository : IConversationRepository
{
    private readonly List<Conversation> conversations = [];
    private readonly List<ConversationMessage> messages = [];
    private readonly Lock gate = new();
    public Task<IReadOnlyList<Conversation>> ListAsync(string userId, CancellationToken cancellationToken = default) { cancellationToken.ThrowIfCancellationRequested(); lock (gate) return Task.FromResult<IReadOnlyList<Conversation>>(conversations.Where(item => item.ClientId == userId || item.TargetUserId == userId).OrderByDescending(item => item.LastAt).ToArray()); }
    public Task<Conversation?> FindAsync(string id, string userId, CancellationToken cancellationToken = default) { cancellationToken.ThrowIfCancellationRequested(); lock (gate) return Task.FromResult(conversations.FirstOrDefault(item => item.Id == id && (item.ClientId == userId || item.TargetUserId == userId))); }
    public Task<Conversation?> CreateAsync(Conversation conversation, CancellationToken cancellationToken = default) { cancellationToken.ThrowIfCancellationRequested(); lock (gate) { var existing = conversations.FirstOrDefault(item => item.ClientId == conversation.ClientId && item.TargetId == conversation.TargetId); if (existing is not null) return Task.FromResult<Conversation?>(existing); conversations.Add(conversation); return Task.FromResult<Conversation?>(conversation); } }
    public async Task<IReadOnlyList<ConversationMessage>> ListMessagesAsync(string conversationId, string userId, CancellationToken cancellationToken = default) { if (await FindAsync(conversationId, userId, cancellationToken) is null) return []; lock (gate) return messages.Where(item => item.ConversationId == conversationId).OrderBy(item => item.SentAt).Take(200).ToArray(); }
    public async Task<ConversationMessage?> AddMessageAsync(string conversationId, string userId, ConversationMessage message, CancellationToken cancellationToken = default) { lock (gate) { if (!conversations.Any(item => item.Id == conversationId && (item.ClientId == userId || item.TargetUserId == userId))) return null; messages.Add(message); var index = conversations.FindIndex(item => item.Id == conversationId); var current = conversations[index]; conversations[index] = new Conversation { Id = current.Id, ClientId = current.ClientId, TargetType = current.TargetType, TargetId = current.TargetId, TargetUserId = current.TargetUserId, TargetName = current.TargetName, QuoteId = current.QuoteId, LastMessage = message.Text[..Math.Min(200, message.Text.Length)], LastAt = message.SentAt }; return message; } }
    public async Task<bool> MarkReadAsync(string conversationId, string userId, CancellationToken cancellationToken = default) { if (await FindAsync(conversationId, userId, cancellationToken) is null) return false; lock (gate) { var now = DateTime.UtcNow; for (var i = 0; i < messages.Count; i++) if (messages[i].ConversationId == conversationId && messages[i].SenderId != userId) messages[i] = new ConversationMessage { Id = messages[i].Id, ConversationId = messages[i].ConversationId, SenderId = messages[i].SenderId, Text = messages[i].Text, SentAt = messages[i].SentAt, ReadAt = now }; return true; } }
}

public sealed class MongoConversationRepository(IMongoDatabase database) : IConversationRepository
{
    private readonly IMongoCollection<BsonDocument> conversations = database.GetCollection<BsonDocument>("conversations");
    private readonly IMongoCollection<BsonDocument> messages = database.GetCollection<BsonDocument>("messages");
    public async Task<IReadOnlyList<Conversation>> ListAsync(string userId, CancellationToken cancellationToken = default) { var filter = Builders<BsonDocument>.Filter.Or(Builders<BsonDocument>.Filter.Eq("clientId", userId), Builders<BsonDocument>.Filter.Eq("targetUserId", userId)); return (await conversations.Find(filter).SortByDescending(item => item["lastAt"]).Limit(100).ToListAsync(cancellationToken)).Select(MapConversation).ToArray(); }
    public async Task<Conversation?> FindAsync(string id, string userId, CancellationToken cancellationToken = default) { var filter = Builders<BsonDocument>.Filter.And(Builders<BsonDocument>.Filter.Eq("_id", id), Builders<BsonDocument>.Filter.Or(Builders<BsonDocument>.Filter.Eq("clientId", userId), Builders<BsonDocument>.Filter.Eq("targetUserId", userId))); var document = await conversations.Find(filter).FirstOrDefaultAsync(cancellationToken); return document is null ? null : MapConversation(document); }
    public async Task<Conversation?> CreateAsync(Conversation conversation, CancellationToken cancellationToken = default) { var duplicate = Builders<BsonDocument>.Filter.And(Builders<BsonDocument>.Filter.Eq("clientId", conversation.ClientId), Builders<BsonDocument>.Filter.Eq("targetId", conversation.TargetId)); var existing = await conversations.Find(duplicate).FirstOrDefaultAsync(cancellationToken); if (existing is not null) return MapConversation(existing); var document = new BsonDocument { ["_id"] = conversation.Id, ["clientId"] = conversation.ClientId, ["targetType"] = conversation.TargetType, ["targetId"] = conversation.TargetId, ["targetUserId"] = conversation.TargetUserId, ["targetName"] = conversation.TargetName, ["lastMessage"] = conversation.LastMessage, ["lastAt"] = new BsonDateTime(conversation.LastAt) }; if (conversation.QuoteId is not null) document["quoteId"] = conversation.QuoteId; await conversations.InsertOneAsync(document, cancellationToken: cancellationToken); return conversation; }
    public async Task<IReadOnlyList<ConversationMessage>> ListMessagesAsync(string conversationId, string userId, CancellationToken cancellationToken = default) { if (await FindAsync(conversationId, userId, cancellationToken) is null) return []; var filter = Builders<BsonDocument>.Filter.Eq("conversationId", conversationId); return (await messages.Find(filter).SortBy(item => item["sentAt"]).Limit(200).ToListAsync(cancellationToken)).Select(MapMessage).ToArray(); }
    public async Task<ConversationMessage?> AddMessageAsync(string conversationId, string userId, ConversationMessage message, CancellationToken cancellationToken = default) { var conversation = await FindAsync(conversationId, userId, cancellationToken); if (conversation is null) return null; var document = new BsonDocument { ["_id"] = message.Id, ["conversationId"] = message.ConversationId, ["senderId"] = message.SenderId, ["text"] = message.Text, ["sentAt"] = new BsonDateTime(message.SentAt) }; await messages.InsertOneAsync(document, cancellationToken: cancellationToken); await conversations.UpdateOneAsync(Builders<BsonDocument>.Filter.Eq("_id", conversationId), Builders<BsonDocument>.Update.Set("lastMessage", message.Text[..Math.Min(200, message.Text.Length)]).Set("lastAt", new BsonDateTime(message.SentAt)), cancellationToken: cancellationToken); return message; }
    public async Task<bool> MarkReadAsync(string conversationId, string userId, CancellationToken cancellationToken = default) { if (await FindAsync(conversationId, userId, cancellationToken) is null) return false; var filter = Builders<BsonDocument>.Filter.And(Builders<BsonDocument>.Filter.Eq("conversationId", conversationId), Builders<BsonDocument>.Filter.Ne("senderId", userId), Builders<BsonDocument>.Filter.Exists("readAt", false)); return (await messages.UpdateManyAsync(filter, Builders<BsonDocument>.Update.Set("readAt", new BsonDateTime(DateTime.UtcNow)), cancellationToken: cancellationToken)).MatchedCount >= 0; }
    private static Conversation MapConversation(BsonDocument d) => new() { Id = d.GetValue("_id").AsString, ClientId = d.GetValue("clientId").AsString, TargetType = d.GetValue("targetType").AsString, TargetId = d.GetValue("targetId").AsString, TargetUserId = d.GetValue("targetUserId").AsString, TargetName = d.GetValue("targetName", "").AsString, QuoteId = d.TryGetValue("quoteId", out var q) ? q.AsString : null, LastMessage = d.GetValue("lastMessage", "").AsString, LastAt = d.GetValue("lastAt").ToUniversalTime() };
    private static ConversationMessage MapMessage(BsonDocument d) => new() { Id = d.GetValue("_id").AsString, ConversationId = d.GetValue("conversationId").AsString, SenderId = d.GetValue("senderId").AsString, Text = d.GetValue("text").AsString, SentAt = d.GetValue("sentAt").ToUniversalTime(), ReadAt = d.TryGetValue("readAt", out var r) ? r.ToUniversalTime() : null };
}
